#include <bits/stdc++.h>
using namespace std;

void solve(){
    int n;
    cin >> n;
    vector<long long> a(3*n);
    for(int i = 0; i < 3*n;i++){
        cin >> a[i];
    }
    
    sort(a.begin(), a.end(), greater<int> ());
    
    vector<long long> pref(3*n + 1, 0);
    for(int i = 0; i < 3*n; i++){
        pref[i+1] = pref[i] + a[i];
    }
    
    long long ans = 0;
    for(int i = 0; i<=n;i++){
        int st = 0;
        int end = n - i;
        while(end - st > 2){
            int mid1 = st + (end - st)/3;
            int mid2 = end - (end - st)/3;
            
            long long val1 = 2LL * pref[i] + pref[i + (2 * mid1)] + 3LL * pref[(3*n) - (2*i) - mid1];
            
            long long val2 = 2LL * pref[i] + pref[i + (2 * mid2)] + 3LL * pref[(3*n) - (2*i) - mid2];
            
            if(val1 < val2){
                st = mid1;
            }else{
                end = mid2;
            }
        }
        
        for(int j = st; j <= end; j++){
            long long curr = 2LL * pref[i] + pref[i + (2 * j)] + 3LL * pref[(3*n) - (2*i) - j];
            if(curr > ans){
                ans = curr;
            }
        }
    }
    cout << ans << endl;
    return;
}

int main() {
	int t;
	cin >> t;
	while(t--){
	    solve();
	}
    return 0;
}
